package com.highpass.runspot.chat.dto;import com.highpass.runspot.chat.domain.*;import java.time.LocalDateTime;import java.util.List;public record ChatMessageResponse(Long messageId,Long senderId,String senderName,ChatMessageType messageType,String content,List<String> imageKeys,LocalDateTime createdAt){public static ChatMessageResponse from(ChatMessage m){return new ChatMessageResponse(m.getId(),m.getSender()==null?null:m.getSender().getId(),m.getSender()==null?null:m.getSender().getName(),m.getMessageType(),m.getContent(),m.getImageKeys(),m.getCreatedAt());}}
